import{H as e,at as t,it as n,vt as r}from"./chunks/framework.dmHZ7NHG.js";var i=JSON.parse(`{"title":"Optics — Light & Perception","description":"","frontmatter":{},"headers":[],"relativePath":"docs/science/optics.md","filePath":"docs/science/optics.md"}`),a={name:`docs/science/optics.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="optics-—-light-perception" tabindex="-1">Optics — Light &amp; Perception <a class="header-anchor" href="#optics-—-light-perception" aria-label="Permalink to “Optics — Light &amp; Perception”">​</a></h1><h2 id="the-sealed-truth" tabindex="-1">The Sealed Truth <a class="header-anchor" href="#the-sealed-truth" aria-label="Permalink to “The Sealed Truth”">​</a></h2><p><strong>Theorem:</strong> <code>Optics.lean</code> (8 theorems, all <code>by decide</code>)</p><p>Reflection is an involution (angle in = angle out, applied twice returns identity). The refractive index n = c/v ≥ 1, so light in a medium is slower than <em>c</em>. Snell&#39;s law: n₁sinθ₁ = n₂sinθ₂ (the consistent case: 4·3 = 3·4). Thin-lens equation: 1/f = 1/d_o + 1/d_i. Dispersion refracts blue more than red. Total internal reflection needs a denser source.</p><p><strong>Why sealed:</strong> Pure geometry and algebra. Angles, indices, focal lengths — all exact rational arithmetic.</p><hr><h2 id="the-honest-boundary" tabindex="-1">The Honest Boundary <a class="header-anchor" href="#the-honest-boundary" aria-label="Permalink to “The Honest Boundary”">​</a></h2><p><strong>What optics CANNOT prove:</strong></p><ul><li>Why light travels in straight lines (that&#39;s quantum mechanics)</li><li>Whether light is waves or particles (both models work for different experiments)</li><li>How perception becomes sight (neural processing, not optics)</li><li>Why the world &quot;looks&quot; the way it does (that&#39;s neuroscience + philosophy)</li></ul><p><strong>Honest scope:</strong> Optics seals the GEOMETRY of light paths. It does NOT explain vision or beauty.</p><hr><h2 id="the-metaphysical-pair" tabindex="-1">The Metaphysical Pair <a class="header-anchor" href="#the-metaphysical-pair" aria-label="Permalink to “The Metaphysical Pair”">​</a></h2><p><strong>The Question:</strong> <em>Does understanding light&#39;s geometry explain why sunsets are beautiful?</em></p><p><strong>The Trinity:</strong></p><table tabindex="0"><thead><tr><th>Perspective</th><th>What It Proves</th><th>What It Cannot</th></tr></thead><tbody><tr><td><strong>Decidable (Sealed)</strong></td><td>Light refracts through air layers by Snell&#39;s law. The wavelength determines colour (blue ~400nm, red ~700nm). Dispersion spreads white into spectrum. The geometry is exact.</td><td>Why <em>you</em> find sunsets beautiful; whether beauty is subjective or objective; whether the physics explains the aesthetic experience</td></tr><tr><td><strong>Honest Boundary</strong></td><td>Knowing the physics of a sunset (Rayleigh scattering, refraction angles, wavelength distribution) does NOT reduce the beauty — it can enhance it. Both are true simultaneously.</td><td>Whether learning the mechanism changes the experience; whether deeper understanding of art diminishes wonder</td></tr><tr><td><strong>Metaphysical</strong></td><td>Can you appreciate a sunset <em>more</em> by understanding its optics, or less? Does mechanism and awe coexist?</td><td>Whether art requires ignorance; whether explanation kills beauty; whether science and poetry are enemies</td></tr></tbody></table><p><strong>The court decides:</strong> Optics seals the mechanism. Aesthetics settles the meaning of beauty.</p><hr><h2 id="read-the-sealed-proof" tabindex="-1">Read the Sealed Proof <a class="header-anchor" href="#read-the-sealed-proof" aria-label="Permalink to “Read the Sealed Proof”">​</a></h2><p><a href="./../../lean/Optics.lean">Optics.lean</a></p><ul><li><code>reflection_is_involution</code></li><li><code>refractive_index_slower_than_c</code></li><li><code>snells_law_consistent</code></li><li><code>thin_lens_equation</code></li><li><code>dispersion_blue_more_than_red</code></li><li><code>total_internal_reflection</code></li></ul><p>Each proven <code>by decide</code>.</p><hr><h2 id="the-research-question" tabindex="-1">The Research Question <a class="header-anchor" href="#the-research-question" aria-label="Permalink to “The Research Question”">​</a></h2><p>If every sunset is perfectly explained by Snell&#39;s law and Rayleigh scattering, then:</p><ol><li>Is the sunset <em>less</em> beautiful when you know the physics?</li><li>Does explanation and wonder compete, or enhance each other?</li><li>Can you love something you completely understand?</li></ol><p><strong>These are open.</strong> Optics does not answer them. Philosophy and art do.</p>`,26)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};